def pol(x, d):
    from itertools import combinations_with_replacement as C
    return np.column_stack([np.ones(len(x))] + [np.prod(x[:, j], 1) for k in range(1, d + 1) for j in C(range(x.shape[1]), k)])

def fn(q, a, k):
    if k == 'sqrt':
        return q / np.sqrt(1 + a * q * q)
    if k == 'cube-rational':
        return q ** 3 / (1 + a * q * q)
    if k == 'cube-sqrt':
        return (q / np.sqrt(1 + a * q * q)) ** 3
    if k == 'cube-tanh':
        return (np.tanh(np.sqrt(a) * q) / np.sqrt(a)) ** 3
    if k == 'cube-sin':
        return (np.sin(np.sqrt(a) * q) / np.sqrt(a)) ** 3
    if k == 'cube-atan':
        return (np.arctan(np.sqrt(a) * q) / np.sqrt(a)) ** 3
    if k == 'cube-tanh3':
        return np.tanh(a * q ** 3) / a
    if k == 'cube-rat6':
        return q ** 3 / np.sqrt(1 + a * q ** 6)
    if k == 'cube-rat3':
        return q ** 3 / (1 + a * abs(q) ** 3)

def _basis(x):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(x))] + [np.prod(x[:, j], axis=1) for d in (1, 2, 3) for j in combinations_with_replacement(range(x.shape[1]), d)])
